n = 0; files = 0
for p in sorted([*root.rglob("*.html"), *root.rglob("*.json"), *root.rglob("*.xml"), *root.rglob("*.txt")]):
    t = p.read_text(encoding="utf-8", errors="surrogateescape"); o = t
    for a, b in R:
        for S in SYMS:
            aa = a.replace("{S}", S); bb = b.replace("{S}", S); c = t.count(aa)
            if c: t = t.replace(aa, bb); n += c
    if t != o:
        p.write_text(t, encoding="utf-8", errors="surrogateescape"); files += 1
print(f"price39-fix: {n} replacements in {files} files")
